class LFUCache {
    struct Entry { int value, freq; std::list<int>::iterator pos; };
    int capacity, minFreq = 0;
    std::unordered_map<int, Entry> entries;
    std::unordered_map<int, std::list<int>> buckets;

    void touch(int key) {
        Entry &e = entries.at(key);
        int f = e.freq;
        buckets[f].erase(e.pos);
        if (buckets[f].empty()) {
            buckets.erase(f);
            if (minFreq == f) ++minFreq;
        }
        ++e.freq;
        buckets[e.freq].push_front(key);
        e.pos = buckets[e.freq].begin();
    }
public:
    LFUCache(int capacity) : capacity(capacity) {}
    int get(int key) {
        auto it = entries.find(key);
        if (it == entries.end()) return -1;
        int value = it->second.value;
        touch(key);
        return value;
    }
    void put(int key, int value) {
        if (capacity == 0) return;
        auto it = entries.find(key);
        if (it != entries.end()) {
            it->second.value = value;
            touch(key);
            return;
        }
        if ((int)entries.size() == capacity) {
            int victim = buckets[minFreq].back();
            buckets[minFreq].pop_back();
            if (buckets[minFreq].empty()) buckets.erase(minFreq);
            entries.erase(victim);
        }
        minFreq = 1;
        buckets[1].push_front(key);
        entries[key] = {value, 1, buckets[1].begin()};
    }
};
